SELECT payload,payload::text FROM (SELECT coalesce(jsonb_agg(jsonb_build_object('raw',to_jsonb(c),'identity',to_jsonb(pg_identify_object('pg_constraint'::regclass,c.oid,0)),'relation',CASE WHEN c.conrelid<>0 THEN to_jsonb(pg_identify_object('pg_class'::regclass,c.conrelid,0)) END,'foreign_relation',CASE WHEN c.confrelid<>0 THEN to_jsonb(pg_identify_object('pg_class'::regclass,c.confrelid,0)) END,'domain',CASE WHEN c.contypid<>0 THEN to_jsonb(pg_identify_object('pg_type'::regclass,c.contypid,0)) END,'definition',pg_get_constraintdef(c.oid,false),'columns',(SELECT jsonb_agg(jsonb_build_object('position',x.position,'attnum',x.attnum,'identity',to_jsonb(pg_identify_object('pg_class'::regclass,c.conrelid,x.attnum))) ORDER BY x.position) FROM unnest(c.conkey) WITH ORDINALITY x(attnum,position) WHERE x.attnum<>0),'foreign_columns',(SELECT jsonb_agg(jsonb_build_object('position',x.position,'attnum',x.attnum,'identity',to_jsonb(pg_identify_object('pg_class'::regclass,c.confrelid,x.attnum))) ORDER BY x.position) FROM unnest(c.confkey) WITH ORDINALITY x(attnum,position))) ORDER BY c.oid),'[]'::jsonb) AS payload FROM pg_constraint c WHERE c.connamespace='public'::regnamespace OR c.conrelid IN (SELECT oid FROM pg_class WHERE relnamespace='public'::regnamespace UNION SELECT reltoastrelid FROM pg_class WHERE relnamespace='public'::regnamespace AND reltoastrelid<>0 UNION SELECT i.indexrelid FROM pg_index i JOIN pg_class c ON c.reltoastrelid=i.indrelid WHERE c.relnamespace='public'::regnamespace)) AS capture